    /// <summary>
    /// Runtime collection of providers plus auth application and request
    /// convenience. Providers own request behavior; <c>Models</c> resolves auth and
    /// delegates each request to the provider that owns the model.
    /// <br /><br />
    /// Read accessors come in three flavors: the unqualified ones (<c>getModels</c>,
    /// <c>getModel</c>, <c>getAvailable</c>) return chat models, the <c>*OfType</c> accessors
    /// return one model type, and <c>getAllModels</c>/<c>getAllAvailable</c> return every type.
    /// </summary>
    type Models =
        abstract getProviders: unit -> Provider<Api>[]
        abstract getProvider: id: string -> Provider<Api> option
        /// <summary>
        /// Sync read of last-known chat models from one provider or all providers.
        /// Best-effort: a provider whose <c>getModels()</c> throws yields no models.
        /// </summary>
        abstract getModels: ?provider: string -> Model<Api>[]
        /// <summary>
        /// Sync runtime chat model lookup against last-known lists. Dynamic model lists
        /// are typed as <c>Model&lt;Api&gt;</c>; narrow with the <c>hasApi()</c> type guard.
        /// </summary>
        abstract getModel: provider: string * id: string -> Model<Api> option
        /// <summary>
        /// Sync read of last-known models of one type from one provider or all providers.
        /// </summary>
        abstract getModelsOfType<'TType>: ``type``: 'TType * ?provider: string -> U3<Model<Api>, ClassifierModel<ClassifierApi>, ImageModel<ImageApi>>[]
        /// <summary>
        /// Sync runtime lookup of a model of one type against last-known lists.
        /// </summary>
        abstract getModelOfType<'TType>: ``type``: 'TType * provider: string * id: string -> U3<Model<Api>, ClassifierModel<ClassifierApi>, ImageModel<ImageApi>> option
        /// <summary>
        /// Sync read of last-known models of every type from one provider or all providers.
        /// </summary>
        abstract getAllModels: ?provider: string -> AnyModel[]
        /// <summary>
        /// Refresh selected configured dynamic providers concurrently (all when <c>providers</c> is omitted).
        /// Provider errors and cancellation are returned without rejecting; static, unknown, and
        /// unconfigured providers are skipped.
        /// </summary>
        abstract refresh: ?options: ModelsRefreshOptions -> JS.Promise<ModelsRefreshResult>
        /// <summary>
        /// Check whether a provider has complete auth configuration without refreshing OAuth.
        /// </summary>
        abstract checkAuth: providerId: string * ?options: AuthOperationOptions -> JS.Promise<AuthCheck option>
        /// <summary>
        /// Return chat models whose providers have complete auth configuration.
        /// </summary>
        abstract getAvailable: ?providerId: string * ?options: AuthOperationOptions -> JS.Promise<Model<Api>[]>
        /// <summary>
        /// Return models of one type whose providers have complete auth configuration.
        /// </summary>
        abstract getAvailableOfType<'TType>: ``type``: 'TType * ?providerId: string * ?options: AuthOperationOptions -> JS.Promise<U3<Model<Api>, ClassifierModel<ClassifierApi>, ImageModel<ImageApi>>[]>
        /// <summary>
        /// Return models of every type whose providers have complete auth configuration.
        /// </summary>
        abstract getAllAvailable: ?providerId: string * ?options: AuthOperationOptions -> JS.Promise<AnyModel[]>
        /// <summary>
        /// Resolve provider-scoped auth by provider id, or provider auth plus static
        /// model headers when passed a model. Includes a source label for status UI.
        /// Resolves <c>undefined</c> when the provider is unknown or unconfigured.
        /// Rejects with <c>ModelsError</c>: code "oauth" when a token refresh fails (the
        /// stored credential is preserved for retry; re-login fixes it), code "auth"
        /// when api-key resolution or the credential store fails. Request paths
        /// surface rejections as stream errors.
        /// </summary>
        abstract getAuth: providerId: string * ?overrides: AuthResolutionOverrides -> JS.Promise<AuthResult option>
        /// <summary>
        /// Resolve provider-scoped auth by provider id, or provider auth plus static
        /// model headers when passed a model. Includes a source label for status UI.
        /// Resolves <c>undefined</c> when the provider is unknown or unconfigured.
        /// Rejects with <c>ModelsError</c>: code "oauth" when a token refresh fails (the
        /// stored credential is preserved for retry; re-login fixes it), code "auth"
        /// when api-key resolution or the credential store fails. Request paths
        /// surface rejections as stream errors.
        /// </summary>
        abstract getAuth: model: AnyModel * ?overrides: AuthResolutionOverrides -> JS.Promise<AuthResult option>
        /// <summary>
        /// Run a provider-owned login flow and persist its returned credential.
        /// </summary>
