        abstract complete<'TApi>: model: Model<'TApi> * context: Context * ?options: obj -> JS.Promise<AssistantMessage>
        abstract streamSimple: model: Model<Api> * context: Context * ?options: ModelsSimpleStreamOptions -> AssistantMessageEventStream
