        abstract streamDeferred: model: Model<Api> * handle: DeferredHandle * ?options: ModelsDeferredFetchOptions -> AssistantMessageEventStream
        abstract fetchDeferred: model: Model<Api> * handle: DeferredHandle * ?options: ModelsDeferredFetchOptions -> JS.Promise<AssistantMessage>
        abstract cancelDeferred: model: Model<Api> * handle: DeferredHandle * ?options: ModelsDeferredCancelOptions -> JS.Promise<unit>
        /// <summary>
